	/** 
	 * jumpstart the process by instantiating2 Note
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		noteId = NoteService.getNoteInstance()
		.createNote( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		NoteService.getNoteInstance()
				.createNote( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.noteSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Note : " + successValue.getNoteId());
							  if (successValue.getNoteId().equals(noteId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfNoteList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Note test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on note consumed")
					);
			subscriber.noteSubscribe( noteId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Note : " + successValue.getNoteId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfNoteList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on note for noteId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Note. 
	 */
	protected Note read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Note" );

		Note entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Note with primary key" );
		msg.append( noteId );
		
		NoteFetchOneSummary fetchOneSummary = new NoteFetchOneSummary( noteId );

		try {
			entity = NoteService.getNoteInstance().getNote( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Note " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Note.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Note." );

		StringBuilder msg = new StringBuilder( "Failed to update a Note : " );        
		Note entity = read();
		UpdateNoteCommand command = generateUpdateCommand();
		command.setNoteId(entity.getNoteId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Note." );

			// for use later on...
			noteId = entity.getNoteId();

			NoteService proxy = NoteService.getNoteInstance();  

			proxy.updateNote( command ).get();

			LOGGER.info( "-- Successfully saved Note - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + noteId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Note.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Note." );

		Note entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Note with id " + noteId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Note with id " + noteId );

			throw e;
		}

		try{
			NoteService.getNoteInstance().delete( new DeleteNoteCommand( entity.getNoteId() ) ).get();
			LOGGER.info( "-- Successfully deleted Note with id " + noteId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Note with id " + noteId );

			throw e;
		}
	}

	/**
	 * get all Notes.
	 */
	protected List<Note> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Notes:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Note : " );        
		List<Note> collection  = new ArrayList<>();

		try {
			// call the static get method on the NoteService
			collection = NoteService.getNoteInstance().getAllNote();
			assertNotNull( collection, "An Empty collection of Note was incorrectly returned.");
			
			// Now print out the values
			Note entity = null;            
			Iterator<Note> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getNoteId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

